import * as THREE from 'three';
const clamp=x=>Math.max(0,Math.min(1,x));
/** An immutable original-mesh BVH. Only reusable math scratch changes per query. */
export function createRopeTriangleContact(positions){
 if(!positions||positions.length%9)throw new TypeError('Original triangle positions required');const count=positions.length/9,indices=new Uint32Array(count),bounds=new Float64Array(count*6);
 for(let i=0;i<count;i++){indices[i]=i;const k=i*9,q=i*6;for(let axis=0;axis<3;axis++){const values=[positions[k+axis],positions[k+3+axis],positions[k+6+axis]];if(!values.every(Number.isFinite))throw new TypeError('Finite original triangle positions required');bounds[q+axis]=Math.min(...values);bounds[q+axis+3]=Math.max(...values);}}
 function build(lo,hi){const min=[Infinity,Infinity,Infinity],max=[-Infinity,-Infinity,-Infinity];for(let k=lo;k<hi;k++){const q=indices[k]*6;for(let a=0;a<3;a++){min[a]=Math.min(min[a],bounds[q+a]);max[a]=Math.max(max[a],bounds[q+a+3]);}}const node={lo,hi,min,max};if(hi-lo>16){const sizes=max.map((v,i)=>v-min[i]),axis=sizes.indexOf(Math.max(...sizes));indices.subarray(lo,hi).sort((a,b)=>(bounds[a*6+axis]+bounds[a*6+axis+3])-(bounds[b*6+axis]+bounds[b*6+axis+3]));const mid=(lo+hi)>>1;node.left=build(lo,mid);node.right=build(mid,hi);}return node;}
 const root=count?build(0,count):null,query=new THREE.Box3(),other=new THREE.Triangle(),first=new THREE.Triangle(),second=new THREE.Triangle(),point=new THREE.Vector3(),d1=new THREE.Vector3(),d2=new THREE.Vector3(),r=new THREE.Vector3(),edge1=new THREE.Vector3(),edge2=new THREE.Vector3(),h=new THREE.Vector3(),s=new THREE.Vector3(),q=new THREE.Vector3();let threshold2=0,lastCandidates=0,lastNodes=0;
 function segmentDistance(p1,q1,p2,q2){d1.copy(q1).sub(p1);d2.copy(q2).sub(p2);r.copy(p1).sub(p2);const a=d1.lengthSq(),e=d2.lengthSq(),f=d2.dot(r);let u=0,v=0;if(a<=1e-18&&e<=1e-18)return r.lengthSq();if(a<=1e-18)v=clamp(f/e);else{const c=d1.dot(r);if(e<=1e-18)u=clamp(-c/a);else{const b=d1.dot(d2),den=a*e-b*b;u=den?clamp((b*f-c*e)/den):0;v=(b*u+f)/e;if(v<0){v=0;u=clamp(-c/a);}else if(v>1){v=1;u=clamp((b-c)/a);}}}return r.addScaledVector(d1,u).addScaledVector(d2,-v).lengthSq();}
 function crosses(p,end,tri){d1.copy(end).sub(p);edge1.copy(tri.b).sub(tri.a);edge2.copy(tri.c).sub(tri.a);h.crossVectors(d1,edge2);const det=edge1.dot(h);if(Math.abs(det)<1e-14)return false;const inverse=1/det;s.copy(p).sub(tri.a);const u=s.dot(h)*inverse;if(u<0||u>1)return false;q.crossVectors(s,edge1);const v=d1.dot(q)*inverse;if(v<0||u+v>1)return false;const t=edge2.dot(q)*inverse;return t>=0&&t<=1;}
 function close(a,b){const av=[a.a,a.b,a.c],bv=[b.a,b.b,b.c];for(let i=0;i<3;i++){if(crosses(av[i],av[(i+1)%3],b)||crosses(bv[i],bv[(i+1)%3],a))return true;b.closestPointToPoint(av[i],point);if(point.distanceToSquared(av[i])<=threshold2)return true;a.closestPointToPoint(bv[i],point);if(point.distanceToSquared(bv[i])<=threshold2)return true;for(let j=0;j<3;j++)if(segmentDistance(av[i],av[(i+1)%3],bv[j],bv[(j+1)%3])<=threshold2)return true;}return false;}
 function visit(node){lastNodes++;if(!node||node.max[0]<query.min.x||node.min[0]>query.max.x||node.max[1]<query.min.y||node.min[1]>query.max.y||node.max[2]<query.min.z||node.min[2]>query.max.z)return false;if(node.left)return visit(node.left)||visit(node.right);for(let i=node.lo;i<node.hi;i++){lastCandidates++;const k=indices[i]*9;other.a.fromArray(positions,k);other.b.fromArray(positions,k+3);other.c.fromArray(positions,k+6);if(close(first,other)||close(second,other))return true;}return false;}
 return{count,get lastCandidates(){return lastCandidates;},get lastNodes(){return lastNodes;},bufferBytes:positions.byteLength+indices.byteLength+bounds.byteLength,intersectsSweptQuad(a,b,c,d,radius){lastCandidates=0;lastNodes=0;threshold2=radius*radius;query.makeEmpty().expandByPoint(a).expandByPoint(b).expandByPoint(c).expandByPoint(d).expandByScalar(radius);first.set(a,b,c);second.set(a,c,d);return visit(root);}};
}
